    outer = json.load(f)

inner = json.loads(outer['result'])
experiments = inner['data']['experiments']

# Helper: search by patterns in exp_id
def find_exps(patterns):
    found = {}
    for eid, edata in experiments.items():
        for p in patterns:
            if p in eid.lower():
                found[eid] = edata
                break
    return found

# Also search in all experiment fields for keywords
def find_exps_deep(keywords):
    found = {}
    for eid, edata in experiments.items():
        estr = json.dumps(edata).lower()
        for k in keywords:
            if k in estr:
                found[eid] = edata
                break
    return found

